from pathlib import Path
p=Path('dashboard.html')
s=p.read_text(encoding='utf-8')

# Tailwind CDN: visual dependency only; no application logic changes.
fa='<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css">'
if 'https://cdn.tailwindcss.com' not in s:
    if fa not in s: raise SystemExit('Font Awesome anchor not found')
    s=s.replace(fa, fa+'\n    <script src="https://cdn.tailwindcss.com"></script>\n    <script>tailwind.config={theme:{extend:{colors:{meshgold:\'#f5c451\',meshnavy:\'#07111f\'}}}}</script>',1)

s=s.replace('<body>','<body class="min-h-screen bg-slate-950 text-slate-100 antialiased">',1)
